export function finaleState(t,f){const q=depotEase((t-f.depotFrameStart)/Math.max(.1,f.depotFrameTime)),crack=depotEase((t-f.depotCrackStart)/Math.max(.1,f.depotCrackTime)),tilt=depotEase((t-f.depotTiltStart)/Math.max(.1,f.depotTiltTime));return {q,crack,tilt,scale:1.13+(f.depotFrameEndScale-1.13)*q,angle:f.depotFrameRotation*tilt*Math.PI/180,skew:-Math.sin(f.depotFrameTilt*tilt*Math.PI/180)*.25,mono:q}}
export function createDepotFinale(){const air=createAtmosphere(),cloud=new Image(),tints=new Map();cloud.src="assets/clouds.png";function tinted(color){if(!cloud.naturalWidth)return null;if(tints.has(color))return tints.get(color);const b=document.createElement("canvas");b.width=cloud.naturalWidth;b.height=cloud.naturalHeight;const g=b.getContext("2d");g.drawImage(cloud,0,0);g.globalCompositeOperation="multiply";g.fillStyle=color;g.fillRect(0,0,b.width,b.height);g.globalCompositeOperation="destination-in";g.drawImage(cloud,0,0);if(tints.size>8)tints.clear();tints.set(color,b);return b}return {paint(c,t,f,photo){const s=finaleState(t,f);c.fillStyle='#080d14';c.fillRect(0,0,960,540);for(const [color,x,seed]of [[f.depotCloudLeft,0,112],[f.depotCloudRight,480,113]]){c.save();c.beginPath();c.rect(x,0,480,540);c.clip();c.fillStyle=color;c.globalAlpha=.15;c.fillRect(x,0,480,540);c.globalAlpha=1;for(let i=0;i<44;i++){const h=n=>{const v=Math.sin(n*127.1+seed)*43758.5;return v-Math.floor(v)},px=x+h(i)*520+Math.sin(t*f.depotStormSpeed/180+i)*26,py=h(i+90)*700-80+(f.depotCloudY-120),r=45+h(i+200)*130,g=c.createRadialGradient(px,py,0,px,py,r);g.addColorStop(0,i%3===0?color+'bb':'#050a13dd');g.addColorStop(.5,i%3===0?color+'88':'#060910bb');g.addColorStop(1,'#00000000');c.globalAlpha=Math.min(1,f.depotStormDensity/100);c.fillStyle=g;c.fillRect(px-r,py-r,r*2,r*2)}c.globalAlpha=1;air.paint(c,t,{density:f.depotStormDensity*.18,thickness:70,speed:f.depotStormSpeed,scale:.8,turbulence:60,opacity:.35,color,seed,path:[[x/960,f.depotCloudY/540],[(x+240)/960,.5],[(x+480)/960,1]]});const flash=Math.pow(Math.max(0,Math.sin(t*f.depotLightningRate*6.28)),55);if(flash>.01){c.save();c.globalCompositeOperation="screen";c.globalAlpha=flash*.6*f.depotLightningBrightness;const glow=c.createRadialGradient(x+260,250,0,x+260,250,330);glow.addColorStop(0,"#fff3ce");glow.addColorStop(1,"#fff3ce00");c.fillStyle=glow;c.fillRect(x,0,480,540);c.restore()}const tex=tinted(color);if(tex){c.save();c.globalAlpha=.72;for(let j=0;j<3;j++){c.save();c.translate(x+230+Math.sin(t*f.depotStormSpeed/220+j)*35,j*200-80+(f.depotCloudY-120));c.rotate((j%2?1:-1)*.28);c.drawImage(tex,-650,-100,1300,450);c.restore()}c.restore()}c.restore();recordSceneAsset(c,{id:'depot-storm-'+seed,kind:'depotStorm',name:seed===112?'Left storm clouds':'Right storm clouds'},[x,0,480,540])}
function bolt(x,seed,opacity,width){c.save();c.globalCompositeOperation='screen';c.globalAlpha=opacity*f.depotLightningBrightness;c.strokeStyle='#fff6ef';c.shadowColor='#fff';c.shadowBlur=24;c.lineWidth=width;c.beginPath();for(let i=0;i<=58;i++){const px=x+Math.sin(i*2.7+seed)*5+Math.sin(i*.6+seed)*22,py=i*540/58;i?c.lineTo(px,py):c.moveTo(px,py)}c.stroke();c.restore()}
bolt(f.depotDividerX,2,.7+Math.pow(Math.max(0,Math.sin(t*1.7)),18)*.3,f.depotDividerWidth);const pulse=Math.pow(Math.max(0,Math.sin(t*f.depotLightningRate*6.28)),55);if(pulse>.02){bolt(160,Math.floor(t*2),pulse,2);bolt(780,Math.floor(t*2)+4,pulse,2);const g=c.createRadialGradient(730,240,1,730,240,380);g.addColorStop(0,'#fff6');g.addColorStop(1,'#fff0');c.fillStyle=g;c.globalAlpha=pulse;c.fillRect(0,0,960,540);c.globalAlpha=1}
recordSceneAsset(c,{id:'depot-lightning',kind:'depotLightning',name:'Storm lightning and glowing divide'},[f.depotDividerX-22,0,44,540]);c.save();c.translate(480,270);c.rotate(s.angle);c.transform(1,s.skew,0,Math.max(.25,Math.cos(f.depotFrameTilt*s.tilt*Math.PI/180)),0,0);c.scale(s.scale,s.scale);c.shadowColor='#000b';c.shadowBlur=30;c.shadowOffsetY=15;const gold=c.createLinearGradient(-500,-280,500,280);for(const [p,v]of [[0,'#281305'],[.2,'#c58b33'],[.4,'#51300d'],[.55,'#e3ac4c'],[.8,'#7f4819'],[1,'#281504']])gold.addColorStop(p,v);c.fillStyle=gold;c.fillRect(-515,-305,1030,610);c.shadowBlur=0;c.shadowOffsetY=0;c.strokeStyle='#d2a044';c.lineWidth=3;for(let i=0;i<4;i++)c.strokeRect(-508+i*5,-298+i*5,1016-i*10,596-i*10);c.fillStyle='#17100a';c.fillRect(-484,-274,968,548);c.save();c.filter=`grayscale(${s.mono})`;c.drawImage(photo,-480,-270,960,540);c.restore();for(let i=0;i<80;i++){const x=-493+i*12.5;c.fillStyle=i%2?'#a86c22':'#e1ad50';for(const y of [-285,285]){c.beginPath();c.ellipse(x,y,3.5,3,0,0,7);c.fill()}}for(let i=0;i<44;i++)for(const x of [-495,495]){c.fillStyle=i%2?'#a46c24':'#d69a38';c.beginPath();c.arc(x,-268+i*12.5,3,0,7);c.fill()}
if(s.crack>0){c.save();c.beginPath();c.rect(-480,-270,960,540);c.clip();const rays=18;for(let i=0;i<rays;i++){const a=i*6.283/rays+.11*Math.sin(i*8),reach=(150+390*(.5+.5*Math.sin(i*29)))*s.crack,x=Math.cos(a)*reach,y=Math.sin(a)*reach;c.strokeStyle='#161719';c.lineWidth=1+2*s.crack;c.beginPath();c.moveTo(-12,0);c.lineTo(x*.45+Math.sin(i)*20,y*.45);c.lineTo(x,y);c.stroke();c.strokeStyle='#e5e3d18a';c.lineWidth=.6;c.stroke();if(s.crack>.45){c.beginPath();c.moveTo(x*.55,y*.55);c.lineTo(x*.6+45,y*.6-35);c.lineTo(x*.8+65,y*.8-20);c.stroke()}}c.restore()}
recordSceneAsset(c,{id:'depot-frame',kind:'depotFrame',name:'Cracking gold picture frame'},[-515,-305,1030,610]);c.restore();return s}}}
